#include "d2d_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/
static void d2d_rx_timeout_service (void * io_base) ;
/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

int d2d_rx (TskTimeout timeout)
{
  CRITICAL ;

  if(tsk_d2d)
    {
      Uart_IO_Base io_base = UART0_BASE ;

      if (!(U0LSR & 0x01))
        {
          os_timeout_arm_set (d2d_rx_timeout_service , (void *) io_base ) ;
            {
              C_ENTER ;
                {
                  U0IER |= 0x01 ;                         // Enable RDA interrupt

                  os_irq_wait (d2d_irq_rx,FALSE,timeout) ; // Wait until data arrives in UART
                  
                }
              C_LEAVE ;
            }
          os_timeout_arm_clr () ;

          return(d2d_rda_rx)    ;
         }

       return ((UInt8) U0RBR) ;
    
    }
  else
    {
      d2d_rda_rx = (-1) ;
      
      #if DBG_D2D == 1
        TRACE("\n[D2D NO RX]");
      #endif      
      
      return  d2d_rda_rx;
    }    
  

}
//--------------------------------------------------------------------------//
static void d2d_rx_timeout_service (void * io_base)
{
  CRITICAL ;

  C_ENTER  ;
    {
      d2d_rda_rx = (-1) ;
	}
  C_LEAVE  ;
}
